INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marktsegmentierung in der IT immer nur nach Alter erfolgt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Kriterien möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Marktsegmentierung für eine IT-Firma durchführe?', 3, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Bestimmen Segmente"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien werden bei der Marktsegmentierung in der IT genutzt?', 5, '[{"text": "Demografie", "correct": true, "because": "Alter, Geschlecht etc."}, {"text": "Verhalten", "correct": true, "because": "Nutzungsverhalten"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Kriterium"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marktsegmentierung verbessert Zielgruppenansprache. b) Sie ist immer unwichtig für IT-Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtig für IT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Marktsegmentierung für IT-Dienstleistungen plane?', 4, '[{"text": "Kundensegmente", "correct": false, "because": "Kern der Segmentierung"}, {"text": "Markttrends", "correct": false, "because": "Beeinflussen Segmente"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Segmentierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktsegmentierung nur für große Märkte relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Märkte"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Marktsegmentierung in der IT?', 3, '[{"text": "Effektive Kundenansprache", "correct": true, "because": "Passt Angebot an"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Segmente", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzt Marktsegmentierung in der IT?', 5, '[{"text": "Geografische Segmentierung", "correct": true, "because": "Nach Region"}, {"text": "Psychografische Segmentierung", "correct": true, "because": "Nach Lebensstil"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Marktsegmentierung hilft Marketing zu optimieren. b) Sie ist immer teuer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Marktsegmentierung in der IT?', 4, '[{"text": "Kundendaten", "correct": false, "because": "Basis der Analyse"}, {"text": "Segmentkriterien", "correct": false, "because": "Bestimmen Gruppen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Segmentierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Marktsegmentierung immer nach geografischen Kriterien?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Kriterien"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Marktsegmentierung in der IT?', 4, '[{"text": "Gezielte Angebote", "correct": true, "because": "Passt an Bedarf"}, {"text": "Effizientere Ressourcennutzung", "correct": true, "because": "Optimiert Marketing"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marktsegmentierung nur für neue Produkte wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für bestehende"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Marktsegmentierung für IT-Dienstleistungen durchzuführen?', 3, '[{"text": "Kundenprofil", "correct": true, "because": "Definiert Segmente"}, {"text": "Schnellste Software", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marktsegmentierung kann Umsatz steigern. b) Sie ist immer unwichtig für IT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wichtig für IT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei der Marktsegmentierung?', 5, '[{"text": "Kaufverhalten", "correct": true, "because": "Zeigt Präferenzen"}, {"text": "Demografische Daten", "correct": true, "because": "Definiert Gruppen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Marktsegmentierung für IT plane?', 3, '[{"text": "Segmentgröße", "correct": false, "because": "Bestimmt Potenzial"}, {"text": "Kundenbedarf", "correct": false, "because": "Steuert Angebot"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Segmentierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Marktsegmentierung immer kostenintensiv?', 3, '[{"text": "Nein", "correct": true, "because": "Kosten variieren"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktsegmentierung nur für B2C-Märkte gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch B2B möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Marktsegmentierung in der IT?', 4, '[{"text": "Relevante Kriterien", "correct": true, "because": "Sichern Effektivität"}, {"text": "Schnellste Analyse", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
